    long long diff = std::abs(x - y);
    if (diff - ch[v1][R] * ch[v2][R] > LLONG_MAX) return 0;
    long long key = x * 10000LL + v1 * 100 + v2;
    if (cache.count(key)) return cache[key];
    if (v1 < R || v2 < R) {
        if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
            int sum = v1 + v2;
            v1 -= cntA[sum];
            v2 -= cntB[sum];
            return ch[v1 + v2][v1];
        }
        return 0;
    }
    long long ans = 0;
    char c = str[v1 + v2 - 1];
